/* VWTIN ($BB22) - Common part for TIE pieces: BJ_ID = B, color from TVWCLE indexed by XPS_TMR (VJFLS flash when beyond
 *   the table), then OBJCEN. X-->explosion queue entry
 * Condition codes out: NZVC.
 */
void vwtin(void)
{
    CK(0xBB22);
    M8(BJ_ID) = B;                                   /* LBB22 */
    B = rd8((uint16_t)(X + XPS_TMR));                /* LBB24  SELECT A COLOR */
    cmp8(B, 0x1F);                                   /* LBB26 */
    CYC(14);
    if (!(CCC | CCZ)) {                              /* LBB28  IFHI  ?BEYOND THE TABLE? */
        D = VJFLS;                                   /* LBB2A  THEN REALLY FLASH */
        CYC(6);
    } else {                                         /* LBB2D  ELSE   */
        U = TVWCLE;                                  /* LBB2F  ELSE SHOW US BEATING IT */
        B = asl8(B);                                 /* LBB32 */
        D = rd16((uint16_t)(U + (int8_t)B));         /* LBB33 */
        CYC(11);
    }
    wr16(Y, D);                                      /* LBB35 */
    Y = (uint16_t)(Y + 2);
    nz16(D);
    CYC(16);
    JSR(objcen);                                     /* LBB37 */
    CYC(5);
    RTS;                                             /* LBB3A */
}

/* BGXPLN ($BB7B) - TEMPORARILY START AT LAST SEQUENCE
 * Condition codes in: C; out: C.
 */
void bgxpln(void)
{
    CK(0xBB7B);
    A = 0x01;                                        /* LBB7B  STARTING PHASE, 00 IS FLAG MEANING END */
    M8(XP_PHS) = A;                                  /* LBB7D */
    D = 0x0001;                                      /* LBB7F  STARTING COUNT */
    wr16(XP_CNT, D);                                 /* LBB82 */
    CYC(19);
    RTS;                                             /* LBB84 */
}

/* VWXPLN ($BB85) - DETH STAR PRETTY STARTING
 * Condition codes out: NZVC.
 */
void vwxpln(void)
{
    uint16_t ea;
    CK(0xBB85);
    A = M8(XP_PHS);                                  /* LBB85 */
    A = asl8(A);                                     /* LBB87 */
    X = TXPPHS;                                      /* LBB88 */
    nz16(X);
    CYC(20);
    ea = rd16((uint16_t)(X + (int8_t)A));            /* LBB8B */
    S = (uint16_t)(S - 2); call_rom(ea);
    xp_nul();                                        /* falls into XP_NUL */
}

/* XP_NUL ($BB8D) - Phase 0 of TXPPHS (XP_PHS = 0 is the flag meaning end): do nothing, RTS. VWXPLN also returns through here
 * Condition codes in: NZVC; out: NZVC.
 */
void xp_nul(void)
{
    CK(0xBB8D);
    CYC(5);
    RTS;                                             /* LBB8D */
}

/* XP_PH0 ($BB98) - FROM DIM TO BRIGHT
 * Condition codes out: NZVC.
 */
void xp_ph0(void)
{
    CK(0xBB98);
    D = (VGCOLR+(VGCRED*0x100));                     /* LBB98  COLOR COMMAND */
    U = (VGSCAL+0x400+0xF0);                         /* LBB9B  STARTING SCALE COMMAND */
    X = rd16(XP_CNT);                                /* LBB9E  NUMBER OF CIRCLES */
    CYC(19);
    JSR(dcircl);                                     /* LBBA0  DRAW CIRCLES */
    D = rd16(XP_CNT);                                /* LBBA3 */
    D = (uint16_t)(D + 0x0002);                      /* LBBA5 */
    wr16(XP_CNT, D);                                 /* LBBA8 */
    cmp16(D, 0x003F);                                /* LBBAA */
    CYC(22);
    if (CCC) {                                       /* LBBAE  IFLO  KEEP GOING */
        D = 0x0001;                                  /* LBBB0 */
        wr16(XP_CNT, D);                             /* LBBB3 */
        M8(XP_PHS) = (uint8_t)(M8(XP_PHS) + 1);      /* LBBB5 */
        CYC(22);
        JSR(auddf);                                  /* LBBB7  FINAL DETH STAR EXPLOSION */
    }
    CYC(5);
    RTS;                                             /* LBBBA */
}

/* XP_PH1 ($BBBB) - BRIGHT BLUE FROM CENTER,RED EXPANSION
 * Condition codes out: NZVC.
 */
void xp_ph1(void)
{
    CK(0xBBBB);
    X = rd16(XP_CNT);                                /* LBBBB  DRAW BLUE CIRCLES */
    D = ((VGCOLR+(VGCBLU*0x100))|0xFF);              /* LBBBD */
    U = (VGSCAL+0x400+0xF0);                         /* LBBC0 */
    CYC(19);
    JSR(dcircl);                                     /* LBBC3 */
    D = rd16(XP_CNT);                                /* LBBC6 */
    D = (uint16_t)(D + 0x0002);                      /* LBBC8 */
    wr16(XP_CNT, D);                                 /* LBBCB */
    CYC(22);
    if (D < 0x003F) {                                /* LBBD1  IFLO  DRAW SOME RED */
        B = 0x3F;                                    /* LBBD3 */
        B = (uint8_t)(B - M8(XP_CNT+1));             /* LBBD5 */
        A = 0;                                       /* LBBD7 */
        X = D;                                       /* LBBD8 */
        D = ((VGCOLR+(VGCRED*0x100))|0xFF);          /* LBBDA */
        CYC(25);
        JSR(dcircl);                                 /* LBBDD */
        D = rd16(XP_CNT);                            /* LBBE0  RED EXPANSION RINGS */
        B = asl8(B);                                 /* LBBE2  ASLD   */
        A = rol8(A);                                 /* LBBE3  ASLD   */
        B = asl8(B);                                 /* LBBE4  ASLD   */
        A = rol8(A);                                 /* LBBE5  ASLD   */
        B = asl8(B);                                 /* LBBE6  ASLD   */
        A = rol8(A);                                 /* LBBE7  ASLD   */
        A = (uint8_t)~A;                             /* LBBE8 */
        B = (uint8_t)~B;                             /* LBBE9 */
        CYC(24);
        if (!(B & 0x80)) {                           /* LBBEA  IFPL   */
            A = (uint8_t)(A - 1);                    /* LBBEC */
            B |= 0x80;                               /* LBBED */
            CYC(4);
        }
        D = (uint16_t)(D + (VGSCAL+0x400+0x70));     /* LBBEF */
        /* TSTB */                                   /* LBBF2 */
        CYC(9);
        if (!(B & 0x80)) {                           /* LBBF3  IFPL   */
            A = (uint8_t)(A - 1);                    /* LBBF5 */
            B &= 0x7F;                               /* LBBF6 */
            CYC(4);
        }
        U = D;                                       /* LBBF8 */
        D = rd16(XP_CNT);                            /* LBBFA */
        B = (uint8_t)(B >> 1);                       /* LBBFC */
        B = (uint8_t)(B >> 1);                       /* LBBFD */
        B &= 0x07;                                   /* LBBFE */
        B ^= 0x07;                                   /* LBC00 */
        B = (uint8_t)(B + 1);                        /* LBC02 */
        X = D;                                       /* LBC03 */
        D = ((VGCOLR+(VGCRED*0x100))|0xFF);          /* LBC05 */
        CYC(38);
        JSR(dring);                                  /* LBC08  DRAW RINGS */
    }
    D = rd16(XP_CNT);                                /* LBC0B */
    cmp16(D, 0x003F);                                /* LBC0D */
    CYC(13);
    if (!CCC) {                                      /* LBC11  IFHS  SETUP FOR NEXT PHASE */
        D = 0x0001;                                  /* LBC13 */
        wr16(XP_CNT, D);                             /* LBC16 */
        M8(XP_PHS) = (uint8_t)(M8(XP_PHS) + 1);      /* LBC18 */
        CYC(22);
        JSR(auddf);                                  /* LBC1A */
    }
    CYC(5);
    RTS;                                             /* LBC1D */
}

/* XP_PH2 ($BC1E) - BRIGHT WHITE FROM CENTER,BLUE EXPANSION
 * Condition codes out: NZVC.
 */
void xp_ph2(void)
{
    CK(0xBC1E);
    X = rd16(XP_CNT);                                /* LBC1E  DRAW WHITE CIRCLES */
    D = ((VGCOLR+(VGCWHT*0x100))|0xFF);              /* LBC20 */
    U = (VGSCAL+0x400+0x70);                         /* LBC23 */
    CYC(19);
    JSR(dcircl);                                     /* LBC26 */
    D = rd16(XP_CNT);                                /* LBC29 */
    D = (uint16_t)(D + 0x0003);                      /* LBC2B */
    wr16(XP_CNT, D);                                 /* LBC2E */
    CYC(22);
    if (D < 0x003F) {                                /* LBC34  IFLO  DRAW SOME BLUE */
        B = 0x3F;                                    /* LBC36 */
        B = (uint8_t)(B - M8(XP_CNT+1));             /* LBC38 */
        A = 0;                                       /* LBC3A */
        X = D;                                       /* LBC3B */
        D = ((VGCOLR+(VGCBLU*0x100))|0xFF);          /* LBC3D */
        CYC(25);
        JSR(dcircl);                                 /* LBC40 */
    }
    D = rd16(XP_CNT);                                /* LBC43  BLUE EXPANSION RINGS */
    CYC(13);
    if (D < 0x003F) {                                /* LBC49  IFLO  DRAW EM */
        B = asl8(B);                                 /* LBC4B  ASLD   */
        A = rol8(A);                                 /* LBC4C  ASLD   */
        B = asl8(B);                                 /* LBC4D  ASLD   */
        A = rol8(A);                                 /* LBC4E  ASLD   */
        B = asl8(B);                                 /* LBC4F  ASLD   */
        A = rol8(A);                                 /* LBC50  ASLD   */
        A = (uint8_t)~A;                             /* LBC51 */
        B = (uint8_t)~B;                             /* LBC52 */
        CYC(19);
        if (!(B & 0x80)) {                           /* LBC53  IFPL   */
            A = (uint8_t)(A - 1);                    /* LBC55 */
            B |= 0x80;                               /* LBC56 */
            CYC(4);
        }
        D = (uint16_t)(D + (VGSCAL+0x400+0x70));     /* LBC58 */
        /* TSTB */                                   /* LBC5B */
        CYC(9);
        if (!(B & 0x80)) {                           /* LBC5C  IFPL   */
            A = (uint8_t)(A - 1);                    /* LBC5E */
            B &= 0x7F;                               /* LBC5F */
            CYC(4);
        }
        U = D;                                       /* LBC61 */
        D = rd16(XP_CNT);                            /* LBC63 */
        B &= 0x0F;                                   /* LBC65 */
        B ^= 0x0F;                                   /* LBC67 */
        B = (uint8_t)(B + 1);                        /* LBC69 */
        X = D;                                       /* LBC6A */
        D = ((VGCOLR+(VGCBLU*0x100))|0xFF);          /* LBC6C */
        CYC(34);
        JSR(dring);                                  /* LBC6F  DRAW RINGS */
    }
    D = rd16(XP_CNT);                                /* LBC72 */
    cmp16(D, 0x0050);                                /* LBC74 */
    CYC(13);
    if (!CCC) {                                      /* LBC78  IFHS  SETUP FOR NEXT PHASE */
        D = 0x0080;                                  /* LBC7A */
        wr16(XP_CNT, D);                             /* LBC7D */
        M8(XP_PHS) = (uint8_t)(M8(XP_PHS) + 1);      /* LBC7F */
        CYC(22);
        JSR(auddf);                                  /* LBC81 */
    }
    CYC(5);
    RTS;                                             /* LBC84 */
}

/* XP_PH3 ($BC85) - CONTINUALLY EXPANDING WHITE RINGS
 * Condition codes out: NZVC.
 */
void xp_ph3(void)
{
    CK(0xBC85);
    D = rd16(XP_CNT);                                /* LBC85 */
    D = (uint16_t)(D - 0x0004);                      /* LBC87 */
    wr16(XP_CNT, D);                                 /* LBC8A */
    cmp16(D, 0x0008);                                /* LBC8C */
    CYC(22);
    if (!CCC) {                                      /* LBC90  IFHS  CONTINUE THIS EXPLOSION PHASE */
        D = (uint16_t)(D + (VGSCAL+0x300));          /* LBC92 */
        U = D;                                       /* LBC95 */
        D = rd16(XP_CNT);                            /* LBC97 */
        A = lsr8(A);                                 /* LBC99  LSRD   */
        B = ror8(B);                                 /* LBC9A  LSRD   */
        B &= 0x3F;                                   /* LBC9B */
        B ^= 0x3F;                                   /* LBC9D */
        X = D;                                       /* LBC9F */
        /* FINAL EXPLOSION */
        D = ((VGCOLR+(VGCWHT*0x100))|0xFF);          /* LBCA1 */
        CYC(40);
        JSR(dring);                                  /* LBCA4 */
        CYC(3);
    } else {                                         /* LBCA7  ELSE   */
        A = 0x00;                                    /* LBCA9  NULL PHASE, ALL DONE */
        M8(XP_PHS) = A;                              /* LBCAB */
        nz8(A);
        CYC(6);
    }
    CYC(5);
    RTS;                                             /* LBCAD */
}

/* DCIRCL ($BCAE) - DRAW CIRCLES
 */
void dcircl(void)
{
    CK(0xBCAE);
    wr16(Y, D);                                      /* LBCAE */
    Y = (uint16_t)(Y + 2);
    CYC(8);
    do {
        CK(0xBCB0);
        D = (VGOFFY&0x1FFF);                         /* LBCB0  Y OFFSET FOR GAME'S SCREEN CENTER */
        wr16(Y, D);                                  /* LBCB3 */
        Y = (uint16_t)(Y + 2);
        D = 0x0000;                                  /* LBCB5  NO OFFSET FOR X */
        wr16(Y, D);                                  /* LBCB8 */
        Y = (uint16_t)(Y + 2);
        wr16(Y, U);                                  /* LBCBA  SCALE */
        Y = (uint16_t)(Y + 2);
        D = VJBCR2;                                  /* LBCBC  BASE CIRCLE WITHOUT COLOR */
        wr16(Y, D);                                  /* LBCBF */
        Y = (uint16_t)(Y + 2);
        U = (uint16_t)(U - 2);                       /* LBCC1 */
        X = (uint16_t)(X - 1);                       /* LBCC3 */
        CYC(54);
    } while (X != 0);                                /* LBCC5  EQEND   */
    CYC(5);
    RTS;                                             /* LBCC7 */
}

/* DRING ($BCC8) - DRAW RINGS
 * Condition codes out: NZVC.
 */
void dring(void)
{
    CK(0xBCC8);
    wr16(Y, D);                                      /* LBCC8 */
    Y = (uint16_t)(Y + 2);
    CYC(8);
    do {
        CK(0xBCCA);
        D = (VGOFFY&0x1FFF);                         /* LBCCA  Y OFFSET FOR GAME'S SCREEN CENTER */
        wr16(Y, D);                                  /* LBCCD */
        Y = (uint16_t)(Y + 2);
        D = 0x0000;                                  /* LBCCF  NO OFFSET FOR X */
        wr16(Y, D);                                  /* LBCD2 */
        Y = (uint16_t)(Y + 2);
        wr16(Y, U);                                  /* LBCD4 */
        Y = (uint16_t)(Y + 2);
        D = VJBCR2;                                  /* LBCD6  BASE STAR CIRCLE WITHOUT COLOR COMMAND */
        wr16(Y, D);                                  /* LBCD9 */
        Y = (uint16_t)(Y + 2);
        D = U;                                       /* LBCDB */
        D = sub16(D, 0x0004);                        /* LBCDD */
        B = and8(B, 0x7F);                           /* LBCE0 */
        U = D;                                       /* LBCE2 */
        X = (uint16_t)(X - 1);                       /* LBCE4 */
        CCZ = (X == 0);
        CYC(67);
    } while (!CCZ);                                  /* LBCE6  EQEND   */
    CYC(5);
    RTS;                                             /* LBCE8 */
}
